-        if (retryAfterMillis != null) delay = retryAfterMillis;
+        if ((status == 429 || status == 503) && retryAfterMillis != null) {
+            delay = Math.min(maxDelayMillis, Math.max(delay, retryAfterMillis));
+        }
         return new Decision(true, delay);
     }
 }

